namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.Add(new Notification(_nextId++, "Welcome to the notification center!", DateTime.UtcNow.AddMinutes(-30)));
        _notifications.Add(new Notification(_nextId++, "Your profile was updated successfully.", DateTime.UtcNow.AddMinutes(-15)));
        _notifications.Add(new Notification(_nextId++, "New feature: dark mode is now available.", DateTime.UtcNow.AddMinutes(-5)));
    }

    /// <summary>Returns all notifications ordered newest-first.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return _notifications.OrderByDescending(n => n.Timestamp).ToList();
        }
    }

    /// <summary>Returns notifications created after the given timestamp.</summary>
    public List<Notification> GetNewSince(DateTime since)
    {
        lock (_lock)
        {
            return _notifications
                .Where(n => n.Timestamp > since)
                .OrderByDescending(n => n.Timestamp)
                .ToList();
        }
    }

    /// <summary>Simulates a new notification arriving at random intervals.</summary>
    public void SimulateIncoming()
    {
        // ~30 % chance each poll cycle produces a new notification
        if (Random.Shared.Next(0, 10) < 3)
        {
            lock (_lock)
            {
                var messages = new[]
                {
                    "Deployment completed for project Alpha.",
                    "You have a new follower.",
                    "Scheduled maintenance window approaching.",
                    "Your export is ready to download.",
                    "Security alert: new login from unknown device.",
                    "Build #42 passed all checks.",
                };
                var msg = messages[Random.Shared.Next(messages.Length)];
                _notifications.Add(new Notification(_nextId++, msg, DateTime.UtcNow));
            }
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@inject NotificationService NotificationSvc
@inject PersistentComponentState PersistState

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group mt-3">
        @foreach (var n in _notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>@n.Message</div>
                <small class="text-muted ms-3 text-nowrap">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;
    private PersistingComponentStateSubscription _persistSub;

    protected override void OnInitialized()
    {
        // Try to restore state persisted during SSR so we don't re-fetch.
        _persistSub = PersistState.RegisterOnPersisting(PersistNotifications);

        if (PersistState.TryTakeFromJson<List<Notification>>("notifications", out var restored))
        {
            _notifications = restored!;
        }
        else
        {
            // First (SSR) render — load from the service.
            _notifications = NotificationSvc.GetAll();
        }
    }

    private Task PersistNotifications()
    {
        PersistState.PersistAsJson("notifications", _notifications);
        return Task.CompletedTask;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // We're now interactive in the browser — start polling.
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct).ConfigureAwait(false);

            // Simulate possible new notifications arriving server-side.
            NotificationSvc.SimulateIncoming();

            var latest = _notifications.Count > 0
                ? _notifications.Max(n => n.Timestamp)
                : DateTime.MinValue;

            var newer = NotificationSvc.GetNewSince(latest);
            if (newer.Count > 0)
            {
                _notifications.InsertRange(0, newer);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _persistSub.Dispose();
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

